 void handleWidget(Intent i){if(i==null)return;String action=i.getStringExtra(SeekyWidget.EXTRA);if(action==null)return;i.removeExtra(SeekyWidget.EXTRA);if(action.equals("cleaner"))handler.postDelayed(()->StorageCleaner.show(this),300);else if(action.equals("search"))goSearch("","Tudo");else if(action.equals("continue")||action.equals("listen")){LastReading.Saved last=LastReading.get(this);if(last.exists()){Intent open=last.intent(this);if(action.equals("listen"))open.putExtra("open_speech",true);try{startActivity(open);}catch(Exception ex){showError(ex);}}else{tab="Livros";render();toast("Abra um livro para começar.");}}else if(action.equals("review")){tab="Estudos";render();handler.postDelayed(()->{if(!dead)new StudyReview(studies).options();},300);}else if(action.equals("update")){((android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(UpdateJob.NOTIFICATION);handler.postDelayed(()->AppUpdates.check(this,true),300);}else if(action.equals("stats"))handler.postDelayed(()->ReadingStats.show(this),300);else if(action.equals("wifi"))handler.postDelayed(()->WifiTransfer.show(this),300);else if(action.equals("agenda"))handler.postDelayed(()->StudyAgenda.show(this),300);else if(action.equals("pomodoro"))handler.postDelayed(()->Pomodoro.show(this),300);else if(action.equals("pomodoro_next"))handler.postDelayed(()->Pomodoro.continueNext(this),300);else if(java.util.Arrays.asList(HomeCategories.NAMES).contains(action))goSearch("",action);}
 void handleQuick(Intent i){if(i.hasExtra("archive_uri")){String uri=i.getStringExtra("archive_uri"),name=i.getStringExtra("archive_name");i.removeExtra("archive_uri");boolean trusted=IncomingUris.trusted(this,i);i.removeExtra(IncomingUris.TOKEN_EXTRA);/* Só pedidos criados pelo próprio Seeky: a MainActivity é exportada. */if(trusted&&uri!=null&&name!=null&&IncomingUris.acceptable(this,Uri.parse(uri))){Catalog.Entry entry=new Catalog.Entry();entry.uri=uri;entry.name=name;entry.mime=MediaFormats.mime(name,null);entry.category="Arquivos";handler.postDelayed(()->ArchiveUi.extract(this,entry),350);}}if(i.getBooleanExtra(FlashSettings.OPEN,false)){i.removeExtra(FlashSettings.OPEN);handler.postDelayed(this::iconSettings,350);}String uri=i.getStringExtra("quick_uri");if(uri==null)return;i.removeExtra("quick_uri");finder.execute(()->{try{Catalog.Entry match=null;if(uri.startsWith("file:")){File f=new File(Uri.parse(uri).getPath());if(!StorageAccess.allowed(this,f)||!f.isFile())throw new IOException("Ficheiro indisponível ou sem acesso.");for(File root:StorageAccess.volumes(this))if(DiskWalker.inside(root,f)){match=StorageAccess.entry(f,root);break;}}else{match=db.byUri(uri);}if(match!=null)match.favorite=db.favoriteUris().contains(match.uri);final Catalog.Entry e=match;if(e!=null)ui(()->fileMenu(e));}catch(Exception e){ui(()->showError(e));}});}
