  shell=column();shell.setClipToPadding(false);shell.setBackground(new BrandSurface(this,BrandSurface.BACKGROUND));shell.setFitsSystemWindows(true);final int side=tab.equals("Livros")?0:14;shell.setPadding(dp(side),0,dp(side),dp(12));
