 void loadResults(){
  cancelSearch();final int serial=querySerial.incrementAndGet();final String q=query,cat=category,ext=extension;final boolean fav=tab.equals("Favoritos"),content=inContent;final int order=sort,l=limit,d=days;final long size=minSize;final boolean desc=descending;final String personal=personalCategory,tag=tagFilter;
  final CancellationSignal signal=new CancellationSignal();querySignal=signal;if(resultCount!=null)resultCount.setText(AppLanguage.text(resultCount.getContext(),"A pesquisar nomes…"));
  final String key=desc+"|"+personal+"|"+tag+"|"+q+"|"+cat+"|"+ext+"|"+fav+"|"+content+"|"+order+"|"+size+"|"+d;
  searchJobs.submit(request->{try{
   List<Catalog.Entry> found=(prefs.getBoolean("flash_mode",true)&&!content&&!fav&&size==0&&d==0&&ext.isEmpty()&&personal.isEmpty()&&tag.isEmpty()&&!q.trim().isEmpty()?db.flash(q,cat,signal):db.query(q,cat,fav,content,order,l,size,d,ext,signal,desc,personal,tag));showMatches(serial,request,key,found,signal,l,"Seeky");
   if(!prefs.getBoolean("flash_mode",true)&&!fav&&!q.trim().isEmpty()&&StorageAccess.all(this)&&found.size()<l){
    try{LinkedHashMap<String,Catalog.Entry> merged=new LinkedHashMap<>();for(Catalog.Entry e:found)merged.put(e.uri,e);List<Catalog.Entry> system=SystemFiles.search(this,db,q,Math.min(l,200),signal);db.decorate(system);long since=d>0?System.currentTimeMillis()-d*86400000L:0;
     for(Catalog.Entry e:system){if(FileOrder.matches(e,personal,tag)&&(cat.equals("Tudo")||cat.equals(e.category))&&e.size>=size&&e.modified>=since&&(ext.isEmpty()||e.name.toLowerCase(Locale.ROOT).endsWith("."+ext)))merged.putIfAbsent(e.uri,e);}
     List<Catalog.Entry> all=new ArrayList<>(merged.values());all.sort(FileOrder.by(order,desc));if(all.size()>l)all=new ArrayList<>(all.subList(0,l));showMatches(serial,request,key,all,signal,l,"Seeky + catálogo Android");
    }catch(OperationCanceledException ex){throw ex;}catch(Exception ignored){}
   }
  }catch(OperationCanceledException ignored){}catch(Exception ex){if(!signal.isCanceled())ui(()->{if(serial==querySerial.get())showError(ex);});}});
 }
 void showMatches(int serial,long request,String key,List<Catalog.Entry> found,CancellationSignal signal,int l,String source){ui(()->{
  if(signal.isCanceled()||!searchJobs.current(request)||serial!=querySerial.get()||list==null||filesAdapter==null)return;boolean changed=!visibleQueryKey.equals(key);visibleQueryKey=key;renderedKey=pageKey();entries=found;resultCount.setText(found.size()+" resultados"+(found.size()==l?" · toque para carregar mais":"")+" · "+source);filesAdapter.notifyDataSetChanged();emptyText.setText(!StorageAccess.all(this)?"Active o acesso geral para pesquisar no armazenamento partilhado.":"Nenhum resultado nos catálogos. Pode procurar nomes directamente fora do catálogo.");resultCount.setOnClickListener(found.size()==l&&l<50000?v->{limit+=100;loadResults();}:null);if(restoreList){Parcelable state=listPositions.get(renderedKey);if(state!=null)list.onRestoreInstanceState(state);restoreList=false;}else if(changed)Motion.rows(list);
 });}
 View fileRow(Catalog.Entry e){FileRowView row=new FileRowView(this,this::favoriteFromRow);row.bind(e,surface,text,muted,accent,prefs.getBoolean("compact",false),query);return row;}
 void favoriteFromRow(Catalog.Entry e,View target){if(busy){toast("Aguarde o fim da operação actual para alterar favoritos.");return;}worker.execute(()->{try{db.favorite(e);ui(()->{if(tab.equals("Favoritos"))loadResults();else if(filesAdapter!=null){filesAdapter.notifyDataSetChanged();if(target instanceof TextView&&e.uri.equals(target.getTag())){((TextView)target).setText(e.favorite?"★":"☆");((TextView)target).setTextColor(e.favorite?accent:muted);target.setContentDescription(e.favorite?"Remover dos favoritos":"Adicionar aos favoritos");Motion.pop(target);}}else{render();}});}catch(Exception ex){ui(()->showError(ex));}});}
