 void importMetadata(List<Catalog.Entry> files){if(busy){toast("Aguarde o fim da operação actual.");return;}dialog().setTitle("Ler título e autor?").setMessage("Completa os campos vazios de "+files.size()+" ficheiros a partir dos metadados disponíveis. Não altera os originais nem os campos já preenchidos.").setPositiveButton("Ler",(d,w)->{startWork();final CancellationSignal token=cancel;worker.execute(()->{int count=0,missing=0;try{db.decorate(files);for(Catalog.Entry e:files){token.throwIfCanceled();report("A ler metadados · "+e.name);try{MetadataExtractor.Values data=MetadataExtractor.read(this,e);if(e.title.isEmpty())e.title=data.title;if(e.author.isEmpty())e.author=data.author;if(!e.title.isEmpty()||!e.author.isEmpty()){db.saveDetails(e);count++;}else missing++;}catch(Exception ex){missing++;}}final int found=count,unreadable=missing;ui(()->toast(found+" ficheiros com dados · "+unreadable+" sem metadados legíveis."));CatalogEvents.publish("Metadados actualizados");}catch(OperationCanceledException ex){ui(()->toast("Importação interrompida; os dados já guardados foram conservados."));}catch(Exception ex){ui(()->showError(ex));}finally{endWork();}});}).setNegativeButton("Cancelar",null).show();}
 EditText metadataInput(String value,String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setTextColor(text);e.setHintTextColor(muted);e.setTextSize(14);e.setText(value);e.setHint(hint);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(300)});return e;}
 void classify(List<Catalog.Entry> targets){if(targets.isEmpty())return;if(busy){toast("Aguarde o fim da operação actual.");return;}finder.execute(()->{try{db.decorate(targets);ui(()->classificationForm(targets));}catch(Exception ex){ui(()->showError(ex));}});}
 void classificationForm(List<Catalog.Entry> targets){boolean single=targets.size()==1;Catalog.Entry first=targets.get(0);LinearLayout c=column();c.setPadding(dp(18),dp(8),dp(18),dp(10));c.addView(label(single?"Dados pessoais do catálogo; o original não é alterado.":"Campos vazios conservam o valor de cada ficheiro.",12,muted));
  c.addView(label("Título",12,muted));EditText title=metadataInput(single?first.title:"","Ex.: Contrato de fornecimento");c.addView(title);
  c.addView(label("Autor",12,muted));EditText author=metadataInput(single?first.author:"","Autor / artista");c.addView(author);
  c.addView(label("Categoria pessoal",12,muted));EditText cat=metadataInput(single?first.customCategory:"","Ex.: Trabalho");c.addView(cat);
  c.addView(label("Marcas / etiquetas",12,muted));EditText tags=metadataInput(single?first.tags:"","Ex.: urgente, clientes, 2026");c.addView(tags);
  c.addView(label("Data personalizada · AAAA-MM-DD",12,muted));EditText date=metadataInput(single?FileOrder.date(first.customDate):"","2026-10-24");c.addView(date);
  c.addView(label("Ordem personalizada · 0 = sem ordem",12,muted));EditText order=metadataInput(single?Long.toString(first.manualOrder):"","Ex.: 1");order.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);c.addView(order);
  if(single)c.addView(button("Ler título e autor do ficheiro",()->{finder.execute(()->{try{MetadataExtractor.Values values=MetadataExtractor.read(this,first);ui(()->{if(!values.title.isEmpty())title.setText(values.title);if(!values.author.isEmpty())author.setText(values.author);toast(values.title.isEmpty()&&values.author.isEmpty()?"Este ficheiro não apresenta título ou autor legíveis.":"Metadados lidos. Reveja e guarde.");});}catch(Exception ex){ui(()->showError(ex));}});}));
  ScrollView scroll=new ScrollView(this);scroll.addView(c);AlertDialog dlg=dialog().setTitle(single?"Classificar ficheiro":targets.size()+" ficheiros · classificar").setView(scroll).setPositiveButton("Guardar",null).setNegativeButton("Cancelar",null).create();dlg.show();dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(busy){toast("Aguarde o fim da operação actual.");return;}final String t=title.getText().toString().trim(),a=author.getText().toString().trim(),ct=cat.getText().toString().trim(),tag=tags.getText().toString().trim(),dateText=date.getText().toString().trim(),orderText=order.getText().toString().trim();final long customDate,manual;
   try{customDate=FileOrder.date(dateText);manual=orderText.isEmpty()?0:Long.parseLong(orderText);if(manual<0||manual>999999999)throw new NumberFormatException();}catch(Exception ex){toast("Reveja a data (AAAA-MM-DD) e a ordem (0 a 999999999).");return;}dlg.dismiss();worker.execute(()->{android.database.sqlite.SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{for(Catalog.Entry e:targets){if(single||!t.isEmpty())e.title=t;if(single||!a.isEmpty())e.author=a;if(single||!ct.isEmpty())e.customCategory=ct;if(single||!tag.isEmpty())e.tags=tag;if(single||!dateText.isEmpty())e.customDate=customDate;if(single||!orderText.isEmpty())e.manualOrder=manual;db.saveDetails(e);}sql.setTransactionSuccessful();}catch(Exception ex){ui(()->showError(ex));return;}finally{sql.endTransaction();}ui(()->{toast("Classificação guardada para "+targets.size()+" ficheiros.");if(tab.equals("Explorar"))loadFolder();else if(tab.equals("Pesquisa")||tab.equals("Favoritos"))loadResults();else render();});record("Classificação",targets.size()==1?targets.get(0).name:targets.size()+" ficheiros","Dados pessoais do catálogo actualizados");CatalogEvents.publish("Classificação actualizada");});
  });
 }
 void requestGlobal(){
  if(StorageAccess.all(this)){toast("O acesso geral já está activo.");return;}
  dialog().setTitle("Pesquisar em todo o armazenamento partilhado").setMessage("Active a autorização geral do Seeky no próximo ecrã. Depois poderá pesquisar na memória, no cartão e no USB disponíveis, sem autorizar cada pasta. As áreas privadas de outras aplicações continuam protegidas pelo Android.").setPositiveButton("Continuar",(d,w)->{
   if(Build.VERSION.SDK_INT>=30){pendingGlobal=true;try{startActivity(new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(Exception ex){try{startActivity(new Intent(Settings.ACTION_MANAGE_ALL_FILES_ACCESS_PERMISSION));}catch(Exception failed){pendingGlobal=false;showError(failed);}}}
   else requestPermissions(new String[]{Manifest.permission.READ_EXTERNAL_STORAGE,Manifest.permission.WRITE_EXTERNAL_STORAGE},31);
  }).setNegativeButton("Mais tarde",null).show();
 }
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==31){render();if(StorageAccess.all(this))scan();else toast("Acesso não concedido. Pode activá-lo nas Preferências.");}}
 void toggleFloat(){
  if(QuickSearchService.floating){startService(new Intent(this,QuickSearchService.class).setAction(QuickSearchService.STOP));toast("Pesquisa flutuante desligada.");handler.postDelayed(this::render,180);return;}
  if(!Settings.canDrawOverlays(this)){dialog().setTitle("Pesquisa em qualquer ecrã").setMessage("Autorize o Seeky a aparecer sobre outras aplicações. Terá uma bolha que pode mover, abrir, recolher e desligar quando quiser.").setPositiveButton("Autorizar",(d,w)->{pendingFloat=true;try{startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(Exception ex){pendingFloat=false;showError(ex);}}).setNegativeButton("Mais tarde",null).show();return;}
  startFloat();
 }
 void startFloat(){
  if(!Settings.canDrawOverlays(this)){toast("Autorize a sobreposição nas Preferências.");return;}
  try{prefs.edit().putBoolean("float_enabled",true).apply();startForegroundService(new Intent(this,QuickSearchService.class).setAction(QuickSearchService.SHOW));if(Build.VERSION.SDK_INT>=33&&!prefs.getBoolean("notification_asked",false)){prefs.edit().putBoolean("notification_asked",true).apply();requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},32);}handler.postDelayed(()->{if(!dead&&QuickSearchService.floating){toast("Toque na bolha para pesquisar. Arraste-a para mover.");render();}},300);}catch(Exception ex){showError(ex);}
 }
