  LinearLayout actions=row();String[] actionsText={"Nova pasta","Exibir","Actualizar"};Runnable[] actionsRun={this::newFolder,this::viewDialog,()->{QuickSearchService.visibleFolder(browseFolder);loadFolder();}};for(int n=0;n<3;n++){TextView action=button(actionsText[n],actionsRun[n]);UiBox.style(action);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(46),1);if(n<2)lp.rightMargin=dp(8);actions.addView(action,lp);}body.addView(actions);gap(body,8);
  resultCount=label("A abrir pasta…",11,muted);body.addView(resultCount);list=makeFileList();filesAdapter=new FilesAdapter();list.setAdapter(filesAdapter);body.addView(list,new LinearLayout.LayoutParams(-1,0,1));
