 void storageCard(LinearLayout parent,File root){LinearLayout card=card();LinearLayout line=row();boolean internal=root.equals(Environment.getExternalStorageDirectory());FrameLayout badge=new FrameLayout(this);badge.setBackground(shape(AppPalette.of(this).tint,14));badge.addView(new Icons(this,internal?"phone":"usb",accent),new FrameLayout.LayoutParams(dp(28),dp(28),Gravity.CENTER));line.addView(badge,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout copy=column();copy.setPadding(dp(12),0,dp(4),0);TextView name=title(StorageAccess.location(root),15);name.setMaxLines(2);copy.addView(name);copy.addView(label(internal?"Armazenamento interno":"Cartão / USB",11,muted));line.addView(copy,new LinearLayout.LayoutParams(0,-2,1));line.addView(new Icons(this,"arrow",muted),new LinearLayout.LayoutParams(dp(21),dp(26)));card.addView(line);try{StatFs fs=new StatFs(root.getPath());long total=fs.getTotalBytes(),used=total-fs.getAvailableBytes();TextView usage=label(Rules.bytes(used)+" / "+Rules.bytes(total),12,muted);usage.setGravity(Gravity.END);card.addView(usage);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress((int)Math.max(0,Math.min(100,used*100.0/Math.max(1,total))));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(accent));bar.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(AppPalette.of(this).tint));card.addView(bar,new LinearLayout.LayoutParams(-1,dp(5)));}catch(Exception ignored){}card.setOnClickListener(v->openFolder(root));Motion.touch(card);parent.addView(card);gap(parent,14);}
 void openFolder(File folder){for(File root:StorageAccess.volumes(this))try{if(DiskWalker.inside(root,folder)){browseRoot=root;browseFolder=folder;folderQuery="";tab="Explorar";render();return;}}catch(Exception ignored){}toast("Pasta indisponível.");}
 void loadFolder(){
  if(browseFolder==null||list==null||!tab.equals("Explorar"))return;final int serial=querySerial.incrementAndGet();final File folder=browseFolder,root=browseRoot;QuickSearchService.visibleFolder(folder);
  finder.execute(()->{try{FolderSnapshot snapshot=FolderSnapshot.read(root,folder,prefs.getBoolean("hidden",true));List<File> files=new ArrayList<>(snapshot.directories);files.addAll(snapshot.files);List<Catalog.Entry> found=new ArrayList<>();Set<String> stars=db.favoriteUris();for(File f:files){Catalog.Entry e=StorageAccess.entry(f,root);e.directory=f.isDirectory();if(e.directory)e.category="Pastas";e.favorite=stars.contains(e.uri);found.add(e);}db.decorate(found);found.sort(FileOrder.by(sort,descending));ui(()->{if(serial!=querySerial.get()||!tab.equals("Explorar"))return;folderEntries=found;filterFolder();if(restoreList){Parcelable state=listPositions.get(renderedKey);if(state!=null)list.onRestoreInstanceState(state);restoreList=false;}});}catch(Exception ex){ui(()->{if(serial==querySerial.get())showError(ex);});}});
 }
 void filterFolder(){if(!tab.equals("Explorar")||filesAdapter==null)return;List<Catalog.Entry> filtered=new ArrayList<>();for(Catalog.Entry e:folderEntries)if((Rules.nameMatches(e.name,folderQuery.trim())||Rules.nameMatches(e.title+" "+e.author+" "+e.tags,folderQuery.trim()))&&(e.directory||FileOrder.matches(e,personalCategory,tagFilter)))filtered.add(e);entries=filtered;resultCount.setText(filtered.size()+" de "+folderEntries.size()+" itens"+(filtered.isEmpty()?" · sem correspondências":""));filesAdapter.notifyDataSetChanged();}
 void folderSortDialog(){organizeDialog();}
 void pinFolder(File folder){Set<String> pins=new LinkedHashSet<>(prefs.getStringSet("pinned_folders",Collections.emptySet()));String path=folder.getPath();boolean removed=pins.remove(path);if(!removed){if(pins.size()>=12){toast("Limite de 12 pastas fixadas.");return;}pins.add(path);}prefs.edit().putStringSet("pinned_folders",pins).apply();toast(removed?"Pasta desafixada.":"Pasta fixada no Início e no Explorar.");}
 void addPinned(LinearLayout c){Set<String> pins=prefs.getStringSet("pinned_folders",Collections.emptySet());if(pins.isEmpty())c.addView(label("Fixe uma pasta pelo símbolo de estrela do explorador.",12,muted));for(String path:new TreeSet<>(pins)){File folder=new File(path);actionCard(c,"folder",folder.getName().isEmpty()?path:folder.getName(),path,()->{if(StorageAccess.allowed(this,folder)&&folder.isDirectory())openFolder(folder);else dialog().setTitle("Pasta indisponível").setMessage(path).setPositiveButton("Remover atalho",(d,w)->{pinFolder(folder);render();}).setNegativeButton("Fechar",null).show();});}}
 void selectVisible(){for(Catalog.Entry e:entries)if(!e.directory&&selected.size()<100)selected.put(e.uri,e);if(filesAdapter!=null)filesAdapter.notifyDataSetChanged();updateTransferBar();}
 void select(Catalog.Entry e){if(e.directory)return;if(selected.containsKey(e.uri))selected.remove(e.uri);else{if(selected.size()>=100){if(filesAdapter!=null)filesAdapter.notifyDataSetChanged();toast("Seleccione até 100 ficheiros de cada vez.");return;}selected.put(e.uri,e);}if(filesAdapter!=null)filesAdapter.notifyDataSetChanged();updateTransferBar();}
 void updateTransferBar(){if(transferBar==null)return;transferBar.removeAllViews();Set<String> clip=prefs.getStringSet("clipboard_files",Collections.emptySet());if(selected.isEmpty()&&clip.isEmpty())return;LinearLayout card=card();card.setPadding(dp(12),dp(5),dp(12),dp(5));HorizontalScrollView sc=new HorizontalScrollView(this);sc.setHorizontalScrollBarEnabled(false);LinearLayout controls=row();
  if(!selected.isEmpty()){controls.addView(label(selected.size()+" seleccionados  ",12,accent));controls.addView(button("Copiar",()->stageTransfer(false)));controls.addView(button("Mover",()->stageTransfer(true)));controls.addView(button("Partilhar",this::shareSelected));controls.addView(button("Compactar ZIP",()->ArchiveUi.compress(this,new ArrayList<>(selected.values()))));controls.addView(button("Colecção",()->addToCollection(new ArrayList<>(selected.values()))));controls.addView(button("Classificar",()->classify(new ArrayList<>(selected.values()))));controls.addView(button("Ler metadados",()->importMetadata(new ArrayList<>(selected.values()))));controls.addView(button("Marcar lista",this::selectVisible));controls.addView(button("Limpar",()->{selected.clear();updateTransferBar();if(filesAdapter!=null)filesAdapter.notifyDataSetChanged();}));TextView remove=button("Eliminar",()->confirmDelete(new ArrayList<>(selected.values())));remove.setTextColor(0xffb93d56);controls.addView(remove);}
  else{controls.addView(label(clip.size()+(prefs.getBoolean("clipboard_move",false)?" para mover  ":" para copiar  "),12,accent));controls.addView(button("Colar aqui",this::pasteFiles));controls.addView(button("Escolher pasta",()->{tab="Explorar";browseFolder=null;render();}));controls.addView(button("Cancelar",()->{prefs.edit().remove("clipboard_files").apply();updateTransferBar();}));}sc.addView(controls);card.addView(sc);transferBar.addView(card);gap(transferBar,6);
 }
 void stageTransfer(boolean move){if(busy){toast("Aguarde o fim da operação actual.");return;}Set<String> files=new LinkedHashSet<>();try{for(Catalog.Entry e:selected.values()){File file=StorageAccess.file(e);if(!StorageAccess.allowed(this,file)||!file.isFile())throw new IOException("Cópia e movimento precisam do acesso geral e de ficheiros disponíveis.");files.add(file.getPath());}if(files.isEmpty())return;prefs.edit().putStringSet("clipboard_files",files).putBoolean("clipboard_move",move).apply();selected.clear();hideKeyboard();tab="Explorar";render();toast("Abra a pasta de destino e toque em Colar aqui.");}catch(Exception ex){showError(ex);}}
 void stageOne(Catalog.Entry e,boolean move){if(busy){toast("Aguarde o fim da operação actual.");return;}if(!selected.isEmpty()){toast("Conclua ou limpe a selecção actual.");return;}selected.put(e.uri,e);stageTransfer(move);if(!prefs.getStringSet("clipboard_files",Collections.emptySet()).isEmpty())selected.clear();updateTransferBar();if(filesAdapter!=null)filesAdapter.notifyDataSetChanged();}
 void shareSelected(){if(selected.isEmpty())return;try{ArrayList<Uri> uris=new ArrayList<>();ClipData clip=null;for(Catalog.Entry e:selected.values()){Uri uri=StorageAccess.shareUri(this,e);uris.add(uri);if(clip==null)clip=ClipData.newRawUri(e.name,uri);else clip.addItem(new ClipData.Item(uri));}Intent i=new Intent(Intent.ACTION_SEND_MULTIPLE).setType("*/*").putParcelableArrayListExtra(Intent.EXTRA_STREAM,uris).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(clip);startActivity(Intent.createChooser(i,"Partilhar "+uris.size()+" ficheiros"));}catch(Exception ex){showError(ex);}}
 void pasteFiles(){if(busy){toast("Aguarde o fim da operação actual.");return;}if(!tab.equals("Explorar")||browseFolder==null){toast("Abra primeiro a pasta de destino.");return;}final Set<String> paths=new LinkedHashSet<>(prefs.getStringSet("clipboard_files",Collections.emptySet()));if(paths.isEmpty())return;final File destination=browseFolder;final boolean move=prefs.getBoolean("clipboard_move",false);dialog().setTitle(move?"Mover ficheiros?":"Copiar ficheiros?").setMessage(paths.size()+" ficheiros para:\n"+destination+"\n\nOs nomes existentes são recusados. No movimento, a origem só é removida depois da verificação da cópia.").setPositiveButton(move?"Mover":"Copiar",(d,w)->performTransfer(paths,destination,move)).setNegativeButton("Cancelar",null).show();}
 void performTransfer(Set<String> paths,File destination,boolean move){if(busy||dead)return;startWork();final CancellationSignal token=cancel;worker.execute(()->{int done=0;List<String> errors=new ArrayList<>();Set<String> remaining=new LinkedHashSet<>(paths);for(String path:paths){if(token.isCanceled()||dead)break;File source=new File(path);try{FileTransfer.Result result=FileTransfer.run(source,destination,move,new FileTransfer.Control(){public boolean cancelled(){return token.isCanceled()||dead;}public boolean allowed(File file){return StorageAccess.allowed(MainActivity.this,file);}public void progress(long bytes,String phase){report(phase+" · "+source.getName()+" · "+Rules.bytes(bytes));}});if(!move)db.copyDetails(Uri.fromFile(source).toString(),Uri.fromFile(result.target).toString(),false);if(move)for(File root:StorageAccess.volumes(this))if(DiskWalker.inside(root,result.target)){db.relocated(Uri.fromFile(source).toString(),StorageAccess.entry(result.target,root));break;}MediaUpdates.changed(this,source,result.target);record(move?"Movido":"Copiado",source.getName(),source.getPath()+" → "+result.target.getPath());remaining.remove(path);done++;}catch(Exception ex){errors.add(source.getName()+": "+ex.getMessage());}finally{try{File target=new File(destination,source.getName());for(File root:StorageAccess.volumes(this))if(StorageAccess.allowed(this,target)&&DiskWalker.inside(root,target)&&target.isFile()){db.metadata(Collections.singletonList(StorageAccess.entry(target,root)));break;}if(move&&!source.exists())db.removePath(source);}catch(Exception ex){errors.add("Catálogo: "+ex.getMessage());}}}prefs.edit().putStringSet("clipboard_files",remaining).putString("last_transfer",done+" de "+paths.size()+" concluídos em "+destination+"\n"+(token.isCanceled()?"Interrompido pelo utilizador.\n":"")+TextUtils.join("\n\n",errors)).apply();QuickSearchService.visibleFolder(destination);CatalogEvents.publish("Ficheiros actualizados");final int completed=done;ui(()->{String message=completed+" de "+paths.size()+" concluídos."+(token.isCanceled()?" Operação interrompida.":"");if(!errors.isEmpty())dialog().setTitle("Resultado da operação").setMessage(message+"\n\n"+TextUtils.join("\n\n",errors)).setPositiveButton("Fechar",null).show();else toast(message);});endWork();});}
 void newFolder(){if(browseFolder==null||!StorageAccess.allowed(this,browseFolder))return;EditText name=new EditText(this);name.setSingleLine(true);dialog().setTitle("Nova pasta").setView(name).setPositiveButton("Criar",(d,w)->{String n=name.getText().toString().trim();if(!Rules.validName(n)){toast("Nome inválido.");return;}File target=new File(browseFolder,n);worker.execute(()->{try{if(!StorageAccess.allowed(this,target)||!target.mkdir())throw new IOException("A pasta já existe ou não pode ser criada.");record("Pasta criada",n,target.getPath());QuickSearchService.visibleFolder(browseFolder);ui(()->{toast("Pasta criada.");render();});}catch(Exception ex){ui(()->showError(ex));}});}).setNegativeButton("Cancelar",null).show();}
 void folderUp(){if(browseFolder==null)return;folderQuery="";if(browseFolder.equals(browseRoot))browseFolder=null;else browseFolder=browseFolder.getParentFile();render();}
 void rememberQuery(){if(query.trim().isEmpty())return;List<String> queries=new ArrayList<>(Arrays.asList(prefs.getString("queries","").split("\n")));queries.remove(query.trim());queries.remove("");queries.add(0,query.trim());if(queries.size()>12)queries=queries.subList(0,12);prefs.edit().putString("queries",TextUtils.join("\n",queries)).apply();}
 void directSearch(){
  if(!StorageAccess.all(this)){requestGlobal();return;}if(tab.equals("Favoritos")){toast("Os favoritos são pesquisados no catálogo. Use Pesquisa para procurar em todo o armazenamento.");return;}
  rememberQuery();final int serial=querySerial.incrementAndGet();if(directCancel!=null)directCancel.cancel();final CancellationSignal token=new CancellationSignal();directCancel=token;final String q=Rules.normalize(query.trim()),cat=category,ext=extension;final long size=minSize,since=days>0?System.currentTimeMillis()-days*86400000L:0;resultCount.setText(AppLanguage.text(resultCount.getContext(),"A procurar no armazenamento partilhado…"));
  finder.execute(()->{LinkedHashMap<String,Catalog.Entry> matches=new LinkedHashMap<>();long deadline=System.nanoTime()+12000000000L;boolean partial=false;try{for(Catalog.Entry e:db.query(query,cat,false,inContent,sort,200,size,days,ext))matches.putIfAbsent(e.uri,e);for(File root:StorageAccess.volumes(this)){DiskWalker.Summary summary=DiskWalker.walk(root,prefs.getBoolean("hidden",true),300000,deadline,new DiskWalker.Visitor(){public boolean cancelled(){return token.isCanceled()||dead||matches.size()>=200;}public void unreadable(File f){}public void file(File f){if(!Rules.nameMatches(f.getName(),q)||f.length()<size||f.lastModified()<since)return;if(!ext.isEmpty()&&!f.getName().toLowerCase(Locale.ROOT).endsWith("."+ext))return;Catalog.Entry e=StorageAccess.entry(f,root);if(!cat.equals("Tudo")&&!cat.equals(e.category))return;matches.putIfAbsent(e.uri,e);}});partial|=summary.limited;if(System.nanoTime()>deadline)break;}publishDirect(serial,matches,partial?" · pesquisa parcial (12 s)":" · armazenamento + catálogo");}catch(InterruptedIOException e){if(!token.isCanceled())publishDirect(serial,matches," · primeiros 200 resultados");}catch(Exception e){ui(()->showError(e));}});
 }
 void publishDirect(int serial,Map<String,Catalog.Entry> matches,String message){List<Catalog.Entry> found=new ArrayList<>(matches.values());db.decorate(found);found.removeIf(e->!FileOrder.matches(e,personalCategory,tagFilter));found.sort(FileOrder.by(sort,descending));ui(()->{if(serial!=querySerial.get())return;entries=found;resultCount.setText(found.size()+" resultados"+message);if(filesAdapter==null){filesAdapter=new FilesAdapter();list.setAdapter(filesAdapter);}else filesAdapter.notifyDataSetChanged();emptyText.setText(AppLanguage.text(emptyText.getContext(),"Nenhum resultado nas áreas pesquisadas. Experimente um nome mais curto ou actualize o catálogo."));});}
 void sortDialog(){organizeDialog();}
 void organizeDialog(){LinearLayout c=column();c.setPadding(dp(18),dp(8),dp(18),dp(8));c.addView(label("Classificar por",12,muted));Spinner fields=spinner(FileOrder.NAMES,sort);c.addView(fields);Spinner order=spinner(new String[]{"Crescente","Decrescente"},descending?1:0);c.addView(order);c.addView(label("Filtrar categoria pessoal / tipo (opcional)",12,muted));EditText cat=metadataInput(personalCategory,"Ex.: Trabalho");c.addView(cat);c.addView(label("Filtrar marca (opcional)",12,muted));EditText tags=metadataInput(tagFilter,"Ex.: urgente");c.addView(tags);dialog().setTitle("Organizar e classificar").setView(c).setPositiveButton("Aplicar",(d,w)->{sort=fields.getSelectedItemPosition();descending=order.getSelectedItemPosition()==1;personalCategory=cat.getText().toString().trim();tagFilter=tags.getText().toString().trim();prefs.edit().putInt("order_field",sort).putBoolean("order_desc",descending).apply();limit=100;if(tab.equals("Explorar"))loadFolder();else if(tab.equals("Pesquisa")||tab.equals("Favoritos"))loadResults();else{tab="Pesquisa";render();}}).setNeutralButton("Limpar filtros",(d,w)->{personalCategory="";tagFilter="";if(tab.equals("Explorar"))loadFolder();else if(tab.equals("Pesquisa")||tab.equals("Favoritos"))loadResults();}).setNegativeButton("Cancelar",null).show();}
 void saveSearch(){if(busy){toast("Aguarde o fim da operação actual para guardar a pesquisa.");return;}final EditText name=new EditText(this);name.setHint(AppLanguage.text(name.getContext(),"Nome da pesquisa"));dialog().setTitle("Guardar pesquisa").setView(name).setPositiveButton("Guardar",(d,w)->{String title=name.getText().toString().trim();if(title.isEmpty()){toast("Escreva um nome para a pesquisa.");return;}if(busy){toast("Aguarde o fim da indexação para guardar.");return;}long id=db.save(title,query,category,inContent);prefs.edit().putString("saved_filters_"+id,minSize+"|"+days+"|"+extension).apply();prefs.edit().putString("saved_organization_"+id,new org.json.JSONArray().put(sort).put(descending).put(personalCategory).put(tagFilter).toString()).apply();rememberQuery();toast("Pesquisa guardada com os filtros nas Ferramentas.");}).setNegativeButton("Cancelar",null).show();}
 void chooseFolder(){if(busy){toast("Aguarde ou cancele a operação actual.");return;}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);try{startActivityForResult(i,10);}catch(Exception e){showError(e);}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(PdfTools.result(this,request,result,data)||ScanActivity.result(this,request,result,data)||PrivateFolder.result(this,request,result,data)||Auth.result(request,result))return;if(AutoBackup.result(this,request,result,data))return;if(request==BookCovers.REQUEST){BookCovers.result(this,result,data);return;}if(request==ImportWork.FOLDER){if(result==RESULT_OK&&data!=null)ImportWork.folder(this,data,studies.prefs.getLong("import_folder_subject",0),studies.prefs.getBoolean("import_folder_books",true));return;}if(request==StudyHub.IMPORT_REPORT){if(studies!=null)studies.result(request,result,data);return;}if(request==BookLibrary.IMPORT){if(result==RESULT_OK&&data!=null)studies.imported(data,true);return;}if(request==50||request==51){notebookResult(request,result,data);return;}if(request>=40&&request<=43){if(studies!=null)studies.result(request,result,data);return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==10){try{int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);getContentResolver().takePersistableUriPermission(uri,flags);db.addRoot(uri);render();scan();}catch(Exception e){showError(e);}}else if(request==20)export(uri);else if(request==21)exportActivity(uri);}
 void rootMenu(String[] root){dialog().setTitle(root[1]).setItems(new String[]{"Actualizar catálogo","Desligar pasta"},(d,n)->{if(n==0)scan();else dialog().setTitle("Desligar esta pasta?").setMessage("Os ficheiros permanecem no dispositivo. A pasta sai apenas do catálogo Seeky.").setPositiveButton("Desligar",(x,w)->{if(busy){toast("Cancele a indexação antes de desligar a pasta.");return;}db.removeRoot(root[0]);try{getContentResolver().releasePersistableUriPermission(Uri.parse(root[0]),Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}render();}).setNegativeButton("Cancelar",null).show();}).show();}
 void startWork(){busy=true;cancel=new CancellationSignal();progressBox.setVisibility(View.VISIBLE);Motion.enter(progressBox,0);}
 long lastReport=0;void report(String message){long now=System.currentTimeMillis();if(now-lastReport<160)return;lastReport=now;ui(()->progressText.setText(message));}
 void endWork(){busy=false;ui(()->{progressBox.setVisibility(View.GONE);render();});}
 void scan(){
  if(StorageAccess.all(this)){prefs.edit().putBoolean("monitor_enabled",true).apply();ensureMonitor(true);toast("A verificar alterações e catálogo do Android. A pesquisa já está disponível.");return;}
  if(busy){toast("Já existe uma operação em curso.");return;}
  boolean global=StorageAccess.all(this);List<String[]> roots=db.roots();if(!global&&roots.isEmpty()){requestGlobal();return;}
  lastRefresh=System.currentTimeMillis();prefs.edit().putLong("last_scan",lastRefresh).apply();startWork();worker.execute(()->{List<String> errors=new ArrayList<>(),logs=new ArrayList<>();int count=0;try{
   if(global){for(File root:StorageAccess.volumes(this)){cancel.throwIfCanceled();try{count+=db.scanDisk(root,cancel,msg->{lastDiskStatus=msg;report(msg);},prefs.getBoolean("hidden",true));logs.add(StorageAccess.location(root)+": "+lastDiskStatus);}catch(InterruptedIOException ex){throw ex;}catch(OperationCanceledException ex){throw ex;}catch(Exception ex){errors.add(StorageAccess.location(root)+": "+ex.getMessage());}}db.migrateFavorites();}
   else for(String[] root:roots){if(root[0].startsWith("file:"))continue;cancel.throwIfCanceled();try{count+=db.scan(root[0],cancel,this::report);}catch(OperationCanceledException ex){throw ex;}catch(Exception ex){errors.add(root[1]+": "+ex.getMessage());}}
   prefs.edit().putString("scan_log",TextUtils.join("\n",logs)+(errors.isEmpty()?"":"\n"+TextUtils.join("\n",errors))).apply();final int n=count;ui(()->{if(errors.isEmpty())toast(n+" ficheiros verificados. Catálogo actualizado.");else dialog().setTitle("Actualização com avisos").setMessage(TextUtils.join("\n\n",errors)+"\n\nOs volumes que falharam conservaram o catálogo anterior.").setPositiveButton("Fechar",null).show();});
  }catch(OperationCanceledException|InterruptedIOException ex){ui(()->toast("Cancelado. O volume interrompido conservou o catálogo anterior."));}finally{endWork();}});
 }
 SafeTrash.Control trashControl(CancellationSignal token){return new SafeTrash.Control(){public boolean allowed(File file){return StorageAccess.allowed(MainActivity.this,file);}public boolean cancelled(){return dead||(token!=null&&token.isCanceled());}};}
 void confirmDelete(List<Catalog.Entry> files){if(files.isEmpty()||busy){if(busy)toast("Aguarde o fim da operação actual.");return;}finder.execute(()->{List<SafeTrash.Plan> plans=new ArrayList<>();List<String> skipped=new ArrayList<>();Set<String> seen=new HashSet<>();SafeTrash.Control control=trashControl(null);for(Catalog.Entry e:files){if(!seen.add(e.uri))continue;try{File source=StorageAccess.file(e);File root=SystemFiles.readableRoot(source,StorageAccess.volumes(this));if(root==null)throw new IOException("Sem acesso geral ou ficheiro fora do armazenamento partilhado.");plans.add(SafeTrash.plan(root,source,control));}catch(Exception ex){skipped.add(e.name+": "+ex.getMessage());}}ui(()->{if(plans.isEmpty()){showError(new IOException("Não há ficheiros locais disponíveis para eliminar. "+TextUtils.join("\n",skipped)));return;}UiPanel p=new UiPanel(this,"Eliminar "+plans.size()+(plans.size()==1?" ficheiro?":" ficheiros?"),"Pode restaurar pela Lixeira","trash");p.note("Os ficheiros sairão das pastas originais e serão guardados na lixeira do mesmo volume. O espaço só é libertado ao eliminar definitivamente.");for(SafeTrash.Plan plan:plans)p.note(plan.source.getName()+" · "+Rules.bytes(plan.size)+"\n"+plan.source.getParent());if(!skipped.isEmpty()){p.section("Não incluídos");p.note(TextUtils.join("\n",skipped));}p.danger("Confirmar · enviar para lixeira",()->deleteFiles(plans));p.show();});});}
 void deleteFiles(List<SafeTrash.Plan> plans){if(busy||dead)return;startWork();final CancellationSignal token=cancel;worker.execute(()->{Set<String> moved=new HashSet<>();List<SafeTrash.Item> sent=new ArrayList<>();List<String> errors=new ArrayList<>();for(SafeTrash.Plan plan:plans){if(token.isCanceled()||dead)break;report("A enviar para lixeira · "+plan.source.getName());try{sent.add(SafeTrash.put(plan,trashControl(token)));MediaUpdates.changed(this,plan.source);record("Enviado para lixeira",plan.source.getName(),plan.source.getPath());moved.add(Uri.fromFile(plan.source).toString());try{db.removePath(plan.source);}catch(Exception ex){errors.add("Actualizar catálogo: "+ex.getMessage());}}catch(Exception ex){errors.add(plan.source.getName()+": "+ex.getMessage());}}Set<String> clipboard=new LinkedHashSet<>(prefs.getStringSet("clipboard_files",Collections.emptySet()));for(SafeTrash.Plan plan:plans)if(moved.contains(Uri.fromFile(plan.source).toString()))clipboard.remove(plan.source.getPath());prefs.edit().putStringSet("clipboard_files",clipboard).apply();CatalogEvents.publish("Lixeira actualizada");ui(()->{for(String uri:moved)selected.remove(uri);String summary=moved.size()+" de "+plans.size()+" enviados para a lixeira."+(token.isCanceled()?" Operação interrompida.":"");if(!sent.isEmpty())dialog().setTitle("Ficheiros na lixeira").setMessage(summary+(errors.isEmpty()?"":"\n\n"+TextUtils.join("\n",errors))).setPositiveButton("Concluir",null).setNeutralButton("Desfazer envio",(d,w)->trashWork(sent,false)).show();else if(!errors.isEmpty())showError(new IOException(summary+"\n\n"+TextUtils.join("\n",errors)));else toast(summary);});endWork();});}
 void showTrash(){if(busy){toast("Aguarde o fim da operação actual.");return;}finder.execute(()->{List<SafeTrash.Item> items=new ArrayList<>();List<String> errors=new ArrayList<>();for(File root:StorageAccess.volumes(this))try{items.addAll(SafeTrash.list(root,trashControl(null)));}catch(Exception ex){errors.add(ex.getMessage());}items.sort((a,b)->Long.compare(b.created,a.created));ui(()->{UiPanel p=new UiPanel(this,"Lixeira",items.size()+" ficheiros recuperáveis","trash");p.note("Ficheiros guardados nos volumes disponíveis. Os restantes ficheiros do telemóvel não são afectados.");if(items.isEmpty())p.note("A lixeira está vazia nos volumes ligados.");int shown=0;for(SafeTrash.Item item:items){if(shown++>=100)break;p.action("document",item.name,Rules.bytes(item.size)+" · "+DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new Date(item.created)),false,()->trashItem(item));}if(items.size()>100)p.note("Mostrados os 100 mais recentes de "+items.size()+". Pode restaurar todos pela opção abaixo.");if(!errors.isEmpty())p.note(TextUtils.join("\n",errors));if(!items.isEmpty()){p.action("back","Restaurar todos","Não substitui ficheiros existentes",false,()->restoreConfirmation(items));p.danger("Esvaziar lixeira",()->purgeConfirmation(items));}p.show();});});}
 void trashItem(SafeTrash.Item item){UiPanel p=new UiPanel(this,item.name,"Lixeira · "+Rules.bytes(item.size),"trash");p.note("Localização original:\n"+item.original.getPath());p.action("back","Restaurar ficheiro","Voltar à pasta original sem substituir outro ficheiro",false,()->restoreConfirmation(Collections.singletonList(item)));p.danger("Eliminar definitivamente",()->purgeConfirmation(Collections.singletonList(item)));p.show();}
 void restoreConfirmation(List<SafeTrash.Item> items){UiPanel p=new UiPanel(this,"Restaurar "+items.size()+" ficheiros?","Voltar às localizações originais","back");p.note("Pastas em falta ou nomes já existentes provocam um aviso. Não se substitui nenhum ficheiro.");for(SafeTrash.Item item:items)p.note(item.name+"\n"+item.original.getParent());p.action("back","Confirmar restauro",null,false,()->trashWork(items,false));p.show();}
 void purgeConfirmation(List<SafeTrash.Item> items){UiPanel p=new UiPanel(this,"Eliminar definitivamente?",items.size()+" ficheiros da lixeira","trash");p.note("Esta operação liberta espaço e não pode ser desfeita pelo Seeky. Não faz sobrescrita segura do suporte. Só os ficheiros listados abaixo serão apagados.");for(SafeTrash.Item item:items)p.note(item.name+" · "+Rules.bytes(item.size));p.danger("Confirmar · apagar definitivamente",()->trashWork(items,true));p.show();}
 void trashWork(List<SafeTrash.Item> items,boolean purge){if(busy||dead)return;startWork();final CancellationSignal token=cancel;worker.execute(()->{int done=0;List<String> errors=new ArrayList<>();for(SafeTrash.Item item:items){if(token.isCanceled()||dead)break;report((purge?"A eliminar definitivamente · ":"A restaurar · ")+item.name);try{if(purge){SafeTrash.purge(item,trashControl(token));record("Eliminado definitivamente",item.name,item.original.getPath());if(!item.original.exists()){String uri=Uri.fromFile(item.original).toString();for(String table:new String[]{"metadata","favorites","recent","history","collection_items"})db.getWritableDatabase().delete(table,"uri=?",new String[]{uri});}}else{File original=SafeTrash.restore(item,trashControl(token));MediaUpdates.changed(this,original);record("Restaurado",item.name,original.getPath());db.metadata(Collections.singletonList(StorageAccess.entry(original,item.root)));QuickSearchService.visibleFolder(original.getParentFile());}done++;}catch(Exception ex){errors.add(item.name+": "+ex.getMessage());}}final int count=done;CatalogEvents.publish("Lixeira actualizada");ui(()->{String result=count+" de "+items.size()+(purge?" eliminados definitivamente.":" restaurados.");if(errors.isEmpty())toast(result);else showError(new IOException(result+"\n\n"+TextUtils.join("\n",errors)));});endWork();});}
 void record(String action,String label,String detail){try{db.activity(action,label,detail);}catch(Exception ex){prefs.edit().putString("activity_warning",ex.getMessage()).apply();}}
 void collections(){finder.execute(()->{try{List<Catalog.CollectionInfo> groups=db.collections();ui(()->{UiPanel panel=new UiPanel(this,"As suas colecções","Ficheiros reunidos sem mover os originais","folder");panel.action("folder","Nova colecção","Crie um espaço para clientes, estudos ou trabalhos",false,()->collectionName(null,null));if(groups.isEmpty())panel.note("Marque ficheiros e escolha Colecção para os reunir aqui.");for(Catalog.CollectionInfo group:groups)panel.action("folder",group.title,group.total+" ligações",false,()->openCollection(group,80));panel.show();});}catch(Exception ex){ui(()->showError(ex));}});}
 void collectionName(Catalog.CollectionInfo group,List<Catalog.Entry> files){EditText name=metadataInput(group==null?"":group.title,"Nome da colecção");name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});AlertDialog dlg=dialog().setTitle(group==null?"Nova colecção":"Renomear colecção").setMessage("Organiza referências aos ficheiros. Não muda as pastas originais.").setView(name).setPositiveButton("Guardar",null).setNegativeButton("Cancelar",null).create();dlg.show();dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{final String title=name.getText().toString().trim();if(title.isEmpty()){name.setError("Escreva um nome.");return;}dlg.dismiss();worker.execute(()->{try{if(group==null){long id=db.createCollection(title);if(files!=null&&!files.isEmpty())db.addCollection(id,files);record("Colecção criada",title,files==null?"Sem ficheiros":files.size()+" ligações");}else{db.renameCollection(group.id,title);record("Colecção renomeada",title,group.title);}ui(()->{toast("Colecção guardada.");collections();});}catch(Exception ex){ui(()->showError(ex));}});});}
 void addToCollection(List<Catalog.Entry> files){if(files.isEmpty())return;finder.execute(()->{try{List<Catalog.CollectionInfo> groups=db.collections();ui(()->{UiPanel panel=new UiPanel(this,"Adicionar à colecção",files.size()+" ficheiros seleccionados","folder");panel.action("folder","Criar nova colecção",null,false,()->collectionName(null,files));for(Catalog.CollectionInfo group:groups)panel.action("folder",group.title,group.total+" ligações",false,()->worker.execute(()->{try{db.addCollection(group.id,files);record("Colecção actualizada",group.title,files.size()+" ficheiros seleccionados");ui(()->toast("Colecção actualizada sem mover ficheiros."));}catch(Exception ex){ui(()->showError(ex));}}));panel.show();});}catch(Exception ex){ui(()->showError(ex));}});}
 void openCollection(Catalog.CollectionInfo group,int limit){finder.execute(()->{try{List<Catalog.Entry> files=db.collectionEntries(group.id,limit);ui(()->{UiPanel panel=new UiPanel(this,group.title,group.total+" ligações · "+files.size()+" apresentados","folder");panel.note("Toque num item para abrir ou gerir a referência. Itens na lixeira, volumes desligados ou ficheiros fora do catálogo podem ficar temporariamente indisponíveis.");for(Catalog.Entry e:files)panel.action(Icons.category(e.category),e.displayTitle(),Rules.bytes(e.size)+" · "+e.category,false,()->collectionItem(group,e));if(files.size()==limit&&limit<500)panel.action("arrow","Carregar mais",null,false,()->openCollection(group,Math.min(500,limit+80)));if(files.isEmpty())panel.note("Nenhum ficheiro desta colecção está disponível no catálogo actual.");panel.action("edit","Renomear colecção",null,false,()->collectionName(group,null));panel.danger("Remover colecção",()->dialog().setTitle("Remover esta colecção?").setMessage("Só a colecção e as suas ligações serão removidas. Os ficheiros permanecem nas pastas e na lixeira.").setPositiveButton("Remover",(d,w)->worker.execute(()->{try{db.removeCollection(group.id);record("Colecção removida",group.title,"Originais conservados");ui(()->{toast("Colecção removida.");collections();});}catch(Exception ex){ui(()->showError(ex));}})).setNegativeButton("Cancelar",null).show());panel.show();});}catch(Exception ex){ui(()->showError(ex));}});}
 void collectionItem(Catalog.CollectionInfo group,Catalog.Entry e){UiPanel panel=new UiPanel(this,e.name,group.title,Icons.category(e.category));panel.primary("Abrir","Pré-visualizar",()->open(e,false),()->preview(e));panel.action("tools","Todas as opções do ficheiro",null,false,()->fileMenu(e));panel.action("back","Remover desta colecção","O ficheiro permanece na pasta original",false,()->worker.execute(()->{try{db.unlinkCollection(group.id,e.uri);record("Referência removida",e.name,group.title);ui(()->toast("Referência removida; ficheiro conservado."));}catch(Exception ex){ui(()->showError(ex));}}));panel.show();}
 void activityLog(){finder.execute(()->{try{List<String[]> events=db.activity();ui(()->{UiPanel panel=new UiPanel(this,"Actividade do Seeky",events.size()+" registos locais · máximo 500","clock");panel.action("document","Exportar actividade em CSV","Escolha onde guardar o relatório",false,this::requestActivityExport);if(events.isEmpty())panel.note("As últimas operações do Seeky aparecerão aqui. Operações feitas noutros gestores não são registadas.");int shown=0;for(String[] event:events){if(shown++>=100)break;String when=DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new Date(Long.parseLong(event[4])));panel.action("clock",event[1]+" · "+event[2],when,false,()->dialog().setTitle(event[1]).setMessage(event[2]+"\n\n"+event[3]+"\n\n"+when).setPositiveButton("Fechar",null).show());}if(events.size()>100)panel.note("Mostrados os 100 mais recentes. A exportação inclui todos os registos guardados.");if(!events.isEmpty())panel.danger("Limpar actividade",()->dialog().setTitle("Limpar actividade?").setMessage("Remove apenas estes registos. Não altera ficheiros, a lixeira ou as colecções.").setPositiveButton("Limpar",(d,w)->worker.execute(()->{db.getWritableDatabase().delete("activity",null,null);ui(()->toast("Registos de actividade limpos."));})).setNegativeButton("Cancelar",null).show());panel.show();});}catch(Exception ex){ui(()->showError(ex));}});}
 void requestActivityExport(){dialog().setTitle("Privacidade do relatório").setItems(new String[]{"Redigido · sem nomes nem caminhos","Completo · inclui nomes e detalhes"},(d,which)->{prefs.edit().putBoolean("activity_redacted",which==0).apply();pickActivityExport();}).setNegativeButton("Cancelar",null).show();}
 void pickActivityExport(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"Seeky_Actividade.csv");try{startActivityForResult(i,21);}catch(Exception ex){showError(ex);}}
 void exportActivity(Uri uri){final boolean redacted=prefs.getBoolean("activity_redacted",true);worker.execute(()->{try(OutputStream stream=getContentResolver().openOutputStream(uri,"wt");Writer out=new OutputStreamWriter(stream,java.nio.charset.StandardCharsets.UTF_8)){if(stream==null)throw new IOException("Destino indisponível.");out.write('\ufeff');CsvFields.row(out,"Data","Operação","Nome","Detalhes");List<String[]> events=db.activity();for(String[] event:events)CsvFields.row(out,DateFormat.getDateTimeInstance().format(new Date(Long.parseLong(event[4]))),event[1],redacted?"[nome omitido]":event[2],redacted?"[detalhes omitidos]":event[3]);out.flush();ui(()->toast("Actividade exportada: "+events.size()+" registos."));}catch(Exception ex){ui(()->showError(ex));}});}
 void fileMenu(Catalog.Entry e){if(e.directory)return;rememberQuery();UiPanel panel=new UiPanel(this,e.name,e.category+" · "+Rules.bytes(e.size),Icons.category(e.category));
  panel.primary("Abrir","Pré-visualizar",()->open(e,false),()->preview(e));panel.quick(new String[]{"star","copy","filters"},new String[]{e.favorite?"Favorito activo":"Favorito","Partilhar","Seleccionar"},new Runnable[]{()->toggleFavorite(e),()->open(e,true),()->select(e)});
  panel.section("Gerir ficheiro");if(ArchiveFiles.accepts(e.name))panel.action("folder","Extrair / descompactar",null,false,()->ArchiveUi.extract(this,e));panel.action("document","Compactar em ZIP",null,false,()->ArchiveUi.compress(this,Collections.singletonList(e)));panel.action("copy","Copiar para outra pasta",null,false,()->stageOne(e,false));panel.action("folder","Mover para outra pasta",null,false,()->stageOne(e,true));panel.action("edit","Renomear",null,false,()->rename(e));if(e.name.toLowerCase(java.util.Locale.ROOT).endsWith(".pdf"))panel.action("pdf","Ferramentas de PDF","Extrair, rodar, comprimir ou juntar",false,()->PdfTools.forFile(this,e));panel.action("lock","Mover para a pasta privada","Esconder da galeria e de outras aplicações",false,()->PrivateFolder.move(this,e));
  panel.section("Organizar");panel.action("folder","Adicionar a uma colecção","Reunir sem mover este ficheiro",false,()->addToCollection(Collections.singletonList(e)));panel.action("filters","Classificar e editar dados","Título, autor, categoria e marcas",false,()->classify(Collections.singletonList(e)));panel.action("folder","Mostrar na pasta",null,false,()->showFolder(e));
  panel.section("Outras opções");panel.action("document","Detalhes do ficheiro",null,false,()->details(e));panel.action("search","Preparar pesquisa no conteúdo",null,false,()->prepareContent(e));panel.action("copy","Copiar localização",null,false,()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Localização",e.path));toast("Localização copiada.");});panel.action("expand","Abrir noutra aplicação",null,false,()->externalOpen(e));panel.danger("Eliminar ficheiro",()->confirmDelete(Collections.singletonList(e)));panel.show();
 }
 void showFolder(Catalog.Entry e){if(!e.uri.startsWith("file:")){details(e);return;}try{File f=StorageAccess.file(e);for(File root:StorageAccess.volumes(this))if(DiskWalker.inside(root,f)){browseRoot=root;browseFolder=f.getParentFile();folderQuery="";tab="Explorar";render();return;}}catch(Exception ex){showError(ex);}}
 void prepareContent(Catalog.Entry e){if(busy){toast("Aguarde ou cancele a operação actual.");return;}dialog().setTitle("Preparar pesquisa no conteúdo?").setMessage("Lê o documento em segundo plano enquanto mantém o Seeky aberto. PDFs: até 32 MB, 80 páginas e 256 mil caracteres; o tempo é verificado entre páginas. Documentos digitalizados precisam de OCR, ainda indisponível. Um índice parcial é identificado no resultado.").setPositiveButton("Preparar",(d,w)->{startWork();final CancellationSignal token=cancel;worker.execute(()->{try{String message=db.content(e,token);ui(()->dialog().setTitle("Pesquisa no conteúdo").setMessage(message).setPositiveButton("Fechar",null).show());CatalogEvents.publish("Conteúdo preparado");}catch(OperationCanceledException|InterruptedIOException ex){ui(()->toast("Preparação cancelada; índice anterior conservado."));}catch(Exception ex){ui(()->showError(ex));}finally{endWork();}});}).setNegativeButton("Cancelar",null).show();}

 void reader(Catalog.Entry e,boolean expanded){try{Intent i=new Intent(this,ReaderActivity.class).setDataAndType(Uri.parse(e.uri),MediaFormats.mime(e.name,e.mime)).putExtra("name",e.name).putExtra("full_screen",expanded);startActivity(i);worker.execute(()->{try{db.opened(e);}catch(Exception ignored){}});}catch(Exception ex){showError(ex);}}
 void open(Catalog.Entry e,boolean share){if(!share&&EbookConvert.supported(e.name)){reader(e,true);return;}if(!share&&ArchiveFiles.accepts(e.name)){ArchiveUi.extract(this,e);return;}if(!share&&ApkInstallActivity.accepts(e.name,e.mime)){ApkInstallActivity.open(this,Uri.parse(e.uri),e.name);return;}if(!share&&!MediaFormats.kind(e.name,e.mime).equals("external")){reader(e,true);return;}openExternal(e,share);}
 void externalOpen(Catalog.Entry e){openExternal(e,false);}
 void openExternal(Catalog.Entry e,boolean share){try{Uri uri=StorageAccess.shareUri(this,e);Intent i=new Intent(share?Intent.ACTION_SEND:Intent.ACTION_VIEW);if(share){i.setType(MediaFormats.mime(e.name,e.mime));i.putExtra(Intent.EXTRA_STREAM,uri);}else i.setDataAndType(uri,MediaFormats.mime(e.name,e.mime));i.setClipData(ClipData.newRawUri(e.name,uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,share?"Partilhar ficheiro":"Abrir ficheiro"));worker.execute(()->{try{db.opened(e);}catch(Exception ignored){}});}catch(Exception ex){showError(ex);}}
 void details(Catalog.Entry e){dialog().setTitle(e.name).setMessage("Título: "+e.displayTitle()+"\nAutor: "+(e.author.isEmpty()?"Não definido":e.author)+"\nCategoria: "+e.displayCategory()+"\nMarcas: "+e.tags+"\nData personalizada: "+FileOrder.date(e.customDate)+"\nOrdem: "+e.manualOrder+"\n\nLocalização: "+e.path+"\n\nTipo: "+e.mime+"\nTamanho: "+(e.size<0?"Desconhecido":Rules.bytes(e.size))+"\nAlterado: "+(e.modified>0?DateFormat.getDateTimeInstance().format(new Date(e.modified)):"Desconhecido")+"\n\nA pesquisa por conteúdo cobre TXT, CSV, MD, JSON, XML, HTML, DOCX, XLSX e PPTX até 16 MB; são lidos até 512 KB de texto por ficheiro.").setPositiveButton("Fechar",null).show();}
 void rename(Catalog.Entry e){if(busy){toast("Aguarde o fim da operação actual.");return;}EditText input=new EditText(this);input.setSingleLine(true);input.setText(e.name);dialog().setTitle("Renomear ficheiro").setMessage("O nome será alterado na pasta original. Pode reverter nas Ferramentas.").setView(input).setPositiveButton("Rever",(d,w)->{String n=input.getText().toString().trim();if(!Rules.validName(n)){toast("Nome inválido. Evite barras e nomes vazios.");return;}dialog().setTitle("Confirmar alteração").setMessage(e.name+"\n↓\n"+n).setPositiveButton("Renomear",(x,y)->{worker.execute(()->{try{db.rename(e,n,true);record("Renomeado",n,e.path);ui(()->{toast("Ficheiro renomeado.");render();});}catch(Exception ex){ui(()->showError(ex));}});}).setNegativeButton("Cancelar",null).show();}).setNegativeButton("Cancelar",null).show();}
 void preview(Catalog.Entry e){if(!MediaFormats.kind(e.name,e.mime).equals("external")||EbookConvert.supported(e.name)){reader(e,false);return;}UiPanel p=new UiPanel(this,e.name,"Pré-visualização",Icons.category(e.category));p.note("Este formato precisa de uma aplicação compatível instalada.");p.action("expand","Abrir noutra aplicação",null,false,()->externalOpen(e));p.show();}
 LinearLayout collapsible(LinearLayout parent,String key,String heading,String description){
  LinearLayout section=column();boolean opened=prefs.getBoolean(key,false);LinearLayout header=row();header.setPadding(dp(15),dp(12),dp(12),dp(12));header.setBackground(shape(surface,18));LinearLayout copy=column();copy.addView(title(heading,15));copy.addView(label(description,11,muted));header.addView(copy,new LinearLayout.LayoutParams(0,-2,1));Icons arrow=new Icons(this,"arrow",accent);arrow.setRotation(opened?90:0);header.addView(arrow,new LinearLayout.LayoutParams(dp(20),dp(24)));section.addView(header);LinearLayout content=column();content.setPadding(0,dp(9),0,0);content.setVisibility(opened?View.VISIBLE:View.GONE);section.addView(content);header.setContentDescription(heading+". "+(opened?"Recolher":"Expandir"));header.setOnClickListener(v->{boolean show=content.getVisibility()!=View.VISIBLE;if(Motion.enabled(this))android.transition.TransitionManager.beginDelayedTransition(section,new android.transition.AutoTransition().setDuration(150));content.setVisibility(show?View.VISIBLE:View.GONE);prefs.edit().putBoolean(key,show).apply();header.setContentDescription(heading+". "+(show?"Recolher":"Expandir"));if(Motion.enabled(this))arrow.animate().rotation(show?90:0).setDuration(150).start();else arrow.setRotation(show?90:0);});Motion.touch(header);parent.addView(section);gap(parent,11);return content;
 }
 void notebookRecovery(){finder.execute(()->{File folder=new File(getFilesDir(),"notebook-recovery");List<File> files=new ArrayList<>();for(String name:new String[]{"before-reader-v2.json","before-notebook-import.json","before-part-restore.json"}){File f=new File(folder,name);if(f.isFile())files.add(f);}ui(()->{if(files.isEmpty()){toast("Ainda não há cópias anteriores de cadernos nesta instalação.");return;}String[] labels=new String[files.size()];for(int i=0;i<labels.length;i++)labels[i]=files.get(i).getName()+" · "+DateFormat.getDateTimeInstance().format(new Date(files.get(i).lastModified()));dialog().setTitle("Cópias locais anteriores dos cadernos").setMessage("Só cadernos activos e marcadores do leitor. Pode recuperar uma parte específica; não inclui originais, Estudos completos ou configurações do gestor.").setItems(labels,(d,index)->readNotebookRecovery(files.get(index))).setNegativeButton("Fechar",null).show();});});}
 void readNotebookRecovery(File file){finder.execute(()->{try{if(file.length()>NotebookBackup.MAX)throw new IOException("Cópia acima do limite.");org.json.JSONObject root;try(InputStream in=new FileInputStream(file)){String json=new String(ContentText.read(in,NotebookBackup.MAX+1),java.nio.charset.StandardCharsets.UTF_8);JsonBudget.check(json,8,50000);root=new org.json.JSONObject(json);}org.json.JSONArray rows=root.getJSONObject("tables").getJSONArray("draft");ui(()->{if(rows.length()==0){toast("Esta cópia não contém partes de cadernos.");return;}int count=Math.min(500,rows.length());String[] labels=new String[count];try{for(int i=0;i<count;i++){org.json.JSONObject row=rows.getJSONObject(i);labels[i]="Parte "+(row.getInt("segment")+1)+" · "+row.getString("uri");}}catch(Exception e){showError(e);return;}dialog().setTitle("Escolher parte a recuperar").setMessage("Mostradas até 500 partes. A confirmação seguinte identifica a referência e o conteúdo que será recuperado.").setItems(labels,(d,index)->{try{org.json.JSONObject row=rows.getJSONObject(index);StudyText value=ReaderStore.decode(row.getString("value"),row.getString("marks"));dialog().setTitle("Recuperar esta parte do caderno?").setMessage(labels[index]+"\n\n"+value.text.length()+" caracteres · "+value.marks.size()+" anotações. Substitui apenas esta identidade de texto na cópia de estudo. O estado actual será guardado antes; se já existia, a recuperação também poderá ser desfeita no leitor. O original não é alterado.").setPositiveButton("Recuperar esta parte",(x,w)->worker.execute(()->{try(ReaderStore reader=new ReaderStore(this)){reader.restoreSaved(row);ui(()->toast("Parte recuperada. Reabra-a no leitor para ver o resultado."));}catch(Exception e){ui(()->showError(e));}})).setNegativeButton("Cancelar",null).show();}catch(Exception e){showError(e);}}).setNegativeButton("Fechar",null).show();});}catch(Exception e){ui(()->showError(e));}});}
 void notebookPicker(boolean restore){dialog().setTitle(restore?"Importar cadernos?":"Exportar cadernos?").setMessage("Inclui cópias de estudo do leitor, notas, destaques, sublinhados e marcadores de todos os documentos. Não inclui os originais, materiais de Estudos, colecções, pesquisas, preferências, credenciais nem o histórico de desfazer. "+(restore?"Registos existentes são conservados; só são acrescentadas identidades em falta. As referências usam os URIs guardados e podem precisar dos mesmos ficheiros/pastas.":"O JSON pode conter texto sensível. Escolha onde o guardar.")).setPositiveButton(restore?"Escolher cópia":"Escolher destino",(d,w)->{try{Intent i=new Intent(restore?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(restore?"*/*":"application/json");if(!restore)i.putExtra(Intent.EXTRA_TITLE,"Seeky_Cadernos.json");startActivityForResult(i,restore?51:50);}catch(Exception e){showError(e);}}).setNegativeButton("Cancelar",null).show();}
 void notebookResult(int request,int result,Intent data){if(result!=RESULT_OK||data==null||data.getData()==null)return;if(busy){toast("Aguarde o fim da operação actual e repita.");return;}final Uri target=data.getData();startWork();worker.execute(()->{File temp=new File(getCacheDir(),"notebook-"+UUID.randomUUID()+".json");try(ReaderStore reader=new ReaderStore(this)){if(request==50){try(OutputStream out=new FileOutputStream(temp)){NotebookBackup.write(reader.getReadableDatabase(),out);}try(InputStream in=new FileInputStream(temp);OutputStream out=getContentResolver().openOutputStream(target,"wt")){if(out==null)throw new IOException("Destino indisponível.");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}ui(()->toast("Cadernos exportados. Não inclui os documentos originais."));}else{try(InputStream in=getContentResolver().openInputStream(target)){if(in==null)throw new IOException("Cópia indisponível.");StudyFiles.copy(in,temp,NotebookBackup.MAX,()->dead||cancel.isCanceled());}NotebookBackup.Result restored=NotebookBackup.restore(this,reader,temp);ui(()->dialog().setTitle("Cadernos importados").setMessage(restored.added+" registos acrescentados · "+restored.kept+" existentes conservados. Foi criada uma cópia local anterior. Não foram substituídos cadernos existentes.").setPositiveButton("Fechar",null).show());}}catch(Exception e){ui(()->showError(e));}finally{temp.delete();endWork();}});}
 void notebookWarning(){
  dialog().setTitle("Rever os cadernos do leitor").setMessage(prefs.getString("reader_warning","")+"\n\nExporte os cadernos para conservar as duas referências antes de resolver o conflito. A mudança do ficheiro pode já ter terminado.")
   .setPositiveButton("Exportar cadernos",(d,w)->notebookPicker(false))
   .setNeutralButton("Marcar como revisto",(d,w)->{prefs.edit().remove("reader_warning").apply();render();})
   .setNegativeButton("Fechar",null).show();
 }
