  actionCard(c,"document","Diagnóstico local","Erros recentes sem conteúdo pessoal",()->{String report=AppDiagnostics.report(this);dialog().setTitle("Diagnóstico do Seeky").setMessage(report).setPositiveButton("Fechar",null).setNeutralButton("Copiar diagnóstico",(d,w)->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Diagnóstico Seeky",report));toast("Diagnóstico copiado.");}).show();});
  actionCard(c,"trash","Lixeira","Restaurar ou eliminar definitivamente os ficheiros",this::showTrash);
  LinearLayout organize=collapsible(c,"tools_organize_open","Organizar e compreender","Duplicados · ficheiros grandes · relatórios");
  actionCard(organize,"copy","Última transferência","Resultado e avisos da cópia ou movimento",()->dialog().setTitle("Última transferência").setMessage(prefs.getString("last_transfer","Ainda não foram realizadas transferências.")).setPositiveButton("Fechar",null).show());
  actionCard(organize,"copy","Encontrar duplicados","Comparação real do conteúdo com SHA-256",this::duplicates);
  actionCard(organize,"storage","Analisar o arquivo","Espaço por tipo, pastas maiores e ficheiros antigos",this::storage);
  actionCard(organize,"document","Ficheiros grandes","A partir de 100 MB, do maior para o menor",()->{query="";category="Tudo";minSize=104857600;days=0;extension="";sort=2;tab="Pesquisa";render();});
  actionCard(organize,"clock","Modificados recentemente","O que mudou nos últimos 7 dias",()->{query="";category="Tudo";minSize=0;days=7;extension="";sort=0;tab="Pesquisa";render();});
  actionCard(organize,"document","Exportar catálogo em CSV","Escolha onde guardar o relatório",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"Seeky_Catalogo.csv");try{startActivityForResult(i,20);}catch(Exception e){showError(e);}});
  actionCard(organize,"back","Desfazer renomeação","Rever e restaurar o nome anterior",this::undo);
  section(c,"Pesquisas guardadas","Toque para abrir; toque prolongado para remover.");
  List<String[]> saved=db.saved();if(saved.isEmpty())c.addView(label("As pesquisas que guardar aparecem aqui.",12,muted));for(String[] s:saved){TextView b=button(s[1]+"  →",()->{query=s[2];category=s[3];inContent=s[4].equals("1");String key="saved_filters_"+s[0];String[] filters=prefs.getString(key,"0|0|").split("\\|",-1);try{minSize=Long.parseLong(filters[0]);days=Integer.parseInt(filters[1]);extension=filters.length>2?filters[2]:"";}catch(Exception ex){minSize=0;days=0;extension="";}try{org.json.JSONArray org=new org.json.JSONArray(prefs.getString("saved_organization_"+s[0],"[]"));if(org.length()==4){sort=org.getInt(0);descending=org.getBoolean(1);personalCategory=org.getString(2);tagFilter=org.getString(3);}}catch(Exception ignored){}tab="Pesquisa";render();});b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setOnLongClickListener(v->{dialog().setTitle("Remover pesquisa guardada?").setMessage(s[1]).setPositiveButton("Remover",(d,w)->{if(busy){toast("Aguarde o fim da operação actual.");return;}db.getWritableDatabase().delete("saved","id=?",new String[]{s[0]});render();}).setNegativeButton("Cancelar",null).show();return true;});c.addView(b);gap(c,7);}
  String history=prefs.getString("queries","");if(!history.isEmpty()){gap(c,16);LinearLayout historyBox=collapsible(c,"tools_history_open","Últimas pesquisas","Reabrir consultas recentes");for(String q:history.split("\n")){if(q.isEmpty())continue;TextView item=button(q,()->goSearch(q,"Tudo"));item.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);historyBox.addView(item);gap(historyBox,6);}}
  section(c,"Multimédia",null);actionCard(c,"audio","Música","Início com recentes e mais ouvidas; artistas, álbuns, pastas e letras",()->LibraryActivity.open(this,MediaLibrary.AUDIO));actionCard(c,"video","Vídeos","Pastas, recentes, anos e favoritos",()->LibraryActivity.open(this,MediaLibrary.VIDEO));actionCard(c,"tune","Equalizador e efeitos","10 bandas, graves, agudos, virtualização e volume",()->EqualizerActivity.open(this));section(c,"Armazenamento e limpeza",null);actionCard(c,"trash","Limpeza e cache","Cache do Seeky, miniaturas e espaço do Android",()->StorageCleaner.show(this));actionCard(c,"android","APKs duplicados","APKs repetidos ou de aplicações já instaladas",()->StorageCleaner.show(this));actionCard(c,"copy","Ficheiros duplicados","Cópias iguais: escolha qual conservar",this::duplicates);actionCard(c,"widget","Widget no ecrã inicial","Pesquisa, meta de leitura ou continuar a ler",this::widgetChoice);section(c,"Ficheiros e PDF",null);actionCard(c,"wifi","Transferir por Wi-Fi","Enviar e receber ficheiros do computador, sem cabo",()->WifiTransfer.show(this));actionCard(c,"pdf","Ferramentas de PDF","Juntar, extrair, rodar, comprimir e fotos para PDF",()->PdfTools.show(this));actionCard(c,"scan","Digitalizar documento","Câmara com recorte automático da folha",()->ScanActivity.open(this));actionCard(c,"storage","Mapa do armazenamento","Pastas que ocupam mais espaço e ficheiros antigos",()->StorageMap.show(this));actionCard(c,"lock","Pasta privada","Esconda ficheiros com a impressão digital ou PIN",()->PrivateFolder.show(this));section(c,"Leitura",null);actionCard(c,"chart","Estatísticas e metas de leitura","Tempo lido, dias seguidos e lembrete diário",()->ReadingStats.show(this));actionCard(c,"globe","Bibliotecas gratuitas","Project Gutenberg e catálogos OPDS",()->OpenLibraries.show(this));actionCard(c,"book","Bíblias","Descarregar mais de 1500 versões ou importar a sua",()->BibleCatalog.show(this));actionCard(c,"dictionary","Vocabulário","Palavras guardadas do dicionário e tradução",()->WordLookup.vocabulary(this));actionCard(c,"edit","As minhas marcações","Destaques, sublinhados e notas: abra no sítio exacto",()->HighlightsActivity.open(this,null));section(c,"Bíblia",null);actionCard(c,"calendar","Estudo bíblico","Leitura de hoje, semana, plano e cartões para decorar",()->BibleStudyActivity.open(this));actionCard(c,"star","Jogo da Bíblia","Passagens e livros em 3 níveis, com recordes",()->BibleGameActivity.open(this));actionCard(c,"note","Bloco de notas","Notas com pastas, cores, tarefas e passagens bíblicas reconhecidas",()->NotepadActivity.open(this));actionCard(c,"bookmark","Passagens guardadas","Guardadas na leitura rápida",()->BibleLinks.saved(this));section(c,"Estudos",null);actionCard(c,"calendar","Provas e trabalhos","Contagem decrescente e lembretes",()->StudyAgenda.show(this));actionCard(c,"clock","Pomodoro","Foco e pausas com o tempo de cada disciplina",()->Pomodoro.show(this));section(c,"Novidades e segurança",null);actionCard(c,"star","Novidades da 5.43","O que mudou e onde experimentar",()->WhatsNew.show(this));actionCard(c,"lock","Bloqueio da aplicação",AppLock.enabled(this)?"Activo":"Impressão digital, rosto ou PIN",()->AppLock.show(this));actionCard(c,"refresh","Actualizações","Procurar nova versão do Seeky",()->AppUpdates.settings(this));actionCard(c,"restore","Cópia automática",AutoBackup.enabled(this)?(AutoBackup.days(this)==1?"Activa · diária":"Activa · semanal"):"Guardar estudos e notas numa pasta",()->AutoBackup.show(this));section(c,"Personalizar",null);actionCard(c,"settings","Temas e preferências","Claro, Escuro, Jade e comportamento",this::settings);actionCard(c,"document","Ajuda e diagnóstico","Versão, permissões e limites",this::help);
